import{_ as a,o as n,c as p,a3 as t}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"WorldBench: Benchmarking Physical Understanding of World Models by Isolating Physics Concepts","description":"","frontmatter":{"title":"WorldBench: Benchmarking Physical Understanding of World Models by Isolating Physics Concepts","arxiv":"2601.21282","date":"2026-01-29","authors":"Rishi Upadhyay, Howard Zhang, Jim Solomon, Ayush Agrawal, Pranay Boreddy, Shruti Satya Narayana, Yunhao Ba, Alex Wong, Celso M de Melo, Achuta Kadambi","categories":"cs.CV","topics":"物理感知视频生成, 世界模型评测, 物理参数估计","outline":[2,2]},"headers":[],"relativePath":"papers/2601.21282.md","filePath":"papers/2601.21282.md","lastUpdated":null}'),l={name:"papers/2601.21282.md"};function e(m,s,r,i,c,h){return n(),p("div",null,[...s[0]||(s[0]=[t('<h1 id="worldbench-benchmarking-physical-understanding-of-world-models-by-isolating-physics-concepts" tabindex="-1">WorldBench: Benchmarking Physical Understanding of World Models by Isolating Physics Concepts <a class="header-anchor" href="#worldbench-benchmarking-physical-understanding-of-world-models-by-isolating-physics-concepts" aria-label="Permalink to &quot;WorldBench: Benchmarking Physical Understanding of World Models by Isolating Physics Concepts&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2601.21282" target="_blank" rel="noreferrer">2601.21282</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-01-29</td></tr><tr><td><strong>作者</strong></td><td>Rishi Upadhyay, Howard Zhang, Jim Solomon, Ayush Agrawal, Pranay Boreddy, Shruti Satya Narayana, Yunhao Ba, Alex Wong, Celso M de Melo, Achuta Kadambi</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>把「物理理解」拆成互不纠缠的单概念场景，再用实拍标定视频从生成结果里<strong>反解出重力加速度、粘度、摩擦系数</strong>，从而定量区分「看起来对的轨迹」与「数值上对的物理」。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/physics-aware">物理感知视频生成</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>arXiv <strong>v1</strong>（2026-01-29）原题《WorldBench: Disambiguating Physics for Diagnostic Evaluation of World Models》，<strong>v2</strong>（2026-08-18）更名为现标题《WorldBench: Benchmarking Physical Understanding of World Models by Isolating Physics Concepts》。本页正文按 <strong>v1</strong> 撰写：上表作者名单为 v1 版，v2 已移除 Pranay Boreddy 与 Shruti Satya Narayana。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>世界基础模型（WFM）最激进的商业叙事是：它可以替代物理仿真软件，直接当合成数据生成器用于机器人训练与自动驾驶。这个叙事有个前提被默认成立却从未被检验——生成视频里的物理<strong>参数</strong>是对的。不是「球看起来在做抛物线运动」，而是「球的下落加速度确实是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0641em;vertical-align:-0.25em;"></span><span class="mord">9.8</span><span class="mspace"> </span><span class="mord"><span class="mord mathrm">m/</span><span class="mord"><span class="mord mathrm">s</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathrm mtight">2</span></span></span></span></span></span></span></span></span></span></span></span>」。</p><p>这两件事的差别是致命的。如果一个模型生成的自由落体加速度是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0641em;vertical-align:-0.25em;"></span><span class="mord">4.2</span><span class="mspace"> </span><span class="mord"><span class="mord mathrm">m/</span><span class="mord"><span class="mord mathrm">s</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathrm mtight">2</span></span></span></span></span></span></span></span></span></span></span></span>，那么用它训出来的抓取策略会系统性地把时机算错，而任何基于视觉相似度或人类偏好的评测都发现不了这一点——人眼分辨不出 4.2 与 9.8 的落体差异，尤其是在没有参照物的短片里。</p><p>WorldBench 要解决的是评测方法论问题：现有物理 benchmark 要么把多个物理概念<strong>纠缠</strong>在同一个场景里（一个球滚下楼梯同时考察透视、碰撞、支撑），要么用<strong>粗粒度二值指标</strong>（物体接触预测 OCP）。前者让失败无法归因，后者无法区分视觉合理与物理精确。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>PHYRE</strong> 是 2D 的，由圆球与矩形条构成，视觉现实性弱、物体过于简化。<strong>CLEVRER</strong> 是视频推理 benchmark，同样结构简单，任务是描述/解释/预测/反事实问答而非视频输出。<strong>MOVi</strong> 系列视觉多样但目标是物体发现而非物理推理。<strong>Physion</strong> 是最接近的——它有 8 类视觉逼真的物理场景（多米诺、支撑、碰撞、容器、下落、连接、滚动、覆盖），但它唯一的评测任务是 OCP（物体接触预测），一个二值输出。<strong>IntPhys 2</strong> 提供了一定的概念粒度，但同样不含针对具体物理参数或材料常数的实验级测试。</p><p>这些工作的共同缺口有两层。第一层是<strong>纠缠</strong>：一个场景同时考验多个概念，模型答错时无法定位是透视错了、碰撞错了还是支撑关系错了。第二层是<strong>输出模态错配</strong>：二值或选择题输出无法刻画速度、加速度、旋转、形变、遮挡这些连续量，而今天的 WFM 输出的恰恰是视频。用二值任务评视频模型，等于用一个比特去测一条轨迹。</p><p>为什么参数级评测此前没做？可以推断成本是主因：要从单目视频里可靠反解物理参数，需要相机内外参标定、可靠的 2D 跟踪、以及深度——最后一项在一般场景里是病态的。WorldBench 的做法是用实验设计绕开它（见 §5），这需要真正搭一套实拍装置，而不是下载数据集。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>先摆已有事实：Cosmos 是当时唯一开源的 video-to-video WFM，其宣传定位就是「为 physical AI 生成合成数据」；SAM2 已经能在遮挡二十多帧后仍稳定跟踪物体；Kubric（PyBullet + Blender）能同时给出物理精确的仿真与高质量渲染，并附带 ground truth 分割、深度、法向、光流；ShapeNet 提供 5.1 万个模型、55 个类别的资产库。</p><p>再看一个经验观察：任何看过 WFM 输出的人都会注意到，球会走出<strong>形状正确</strong>的抛物线。这个观察是整篇论文的种子——如果轨迹形状对而参数错，那么所有基于形状/外观的指标都会给高分，而模型作为合成数据源是不合格的。要证明这一点，必须把「形状」和「参数」在测量上分开。</p><p>于是路径是：<strong>分离</strong>这一步要求每个场景只考一个概念，所以要手工设计场景而不是采集野外视频；<strong>参数</strong>这一步要求能从视频里量出数，而单目深度不可靠，那就把实验设计成深度恒定——让物体只在与相机平面平行的平面内运动，深度可以直接尺量。剩下的就是标定（背景放棋盘格标外参，事先标内参）、跟踪（SAM2 取质心）、拟合（二次曲线取加速度，直线拟合取终端速度），最后代进课本公式换算成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">μ</span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">η</span></span></span></span>。最关键的一步是<strong>先在自己实拍的视频上验证整条流水线</strong>——如果它量不准真实世界，量模型输出就毫无意义。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>视觉合理性与物理精确性是两个可以独立失败的量，而现有 benchmark 只测得到前者。要把它们分开，唯一的办法是让评测输出一个<strong>有单位的数</strong>：从生成视频里反解出 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">η</span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">μ</span></span></span></span>，再和课本值比。为了让这个反解可行，就得牺牲场景复杂度——把深度固定、把概念隔离、把参照物放进画面。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>任务被定义为「受约束的视频预测」（constrained video prediction）：给模型一小段输入视频，让它续写；每段视频只考一个物理概念或常数。</p><p><strong>子集一：直觉物理理解。</strong> 四个概念、共 15 个场景、469 段视频（425 仿真 + 44 实拍），每段 132 帧，附 ground truth 分割（仿真视频另附深度、法向、光流）。仿真用 Kubric 渲染，物体从 ShapeNet 全类别采样以保证形状、纹理、尺寸多样。</p><ul><li><strong>运动物理</strong>（3 场景）：弹跳球（随机化初始高度与弹性材质）、双物体下落（随机形状与初始位置）、双物体抛物线对撞（随机形状、位置、初速度，不必共面）。</li><li><strong>物体恒存性</strong>（5 场景）：物体从墙后经过、物体经过多根细柱反复隐现、球在凸起方块后弹跳、球在两墙之间滚动并被方块周期性遮挡、大球遮挡小球的双球弹跳。</li><li><strong>支撑关系</strong>（3 场景）：多米诺、球滚下斜坡被挡块停住、物体悬在桌沿（考察「接触即支撑」是不够的，还需质量分布与支撑分布匹配）。</li><li><strong>透视/尺度</strong>（2 场景）：物体朝相机运动、物体远离相机。</li></ul><p>评测流程：用 ground truth 分割在首帧取 bounding box，以此 prompt SAM2 在生成视频里传播，逐帧与 GT mask 比 mIoU（前景），并对非物体像素算 background RMSE（因为所有背景都是静止的，这一项直接量「模型有没有把环境搞乱」）。SAM2 本身的可靠性经过验证：与人工标注的实拍部分对比，整体 mIoU 达 0.9445；论文还展示了物体被遮挡 20 多帧后 SAM2 仍能重新跟上。</p><p><strong>子集二：物理参数估计。</strong> 三套实验、共 279 段（实拍 234 + 仿真 45）。全部用 iPhone 13 慢动作拍摄，背景放棋盘格。</p><ul><li><strong>重力</strong>（51 段实拍：17 直落 + 34 抛物）。物体形状尺寸随机，抛射角与轨迹随机，均选取空气阻力可忽略的物体。视频剪裁到首帧物体已在空中自由飞行。画面里加一把尺子给模型尺度线索。</li><li><strong>粘度</strong>（80 段：甘油 32、玉米糖浆 30、蜂蜜 18）。钢球落入烧杯，从终端速度反推粘度。因为粘度随温度与吸水变化，所有视频在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">7</span><span class="mord"><span class="mord">5</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6741em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">∘</span></span></span></span></span></span></span></span><span class="mord mathrm">F</span></span></span></span> 同一场次内采集。烧杯带刻度提供尺度。</li><li><strong>摩擦</strong>（103 段：木 30、橡胶 19、80 目砂纸 18、3000 目砂纸 18、塑料 18）。钢块沿铺不同材料的斜面下滑，斜面角度逐次随机。</li></ul><p>反解流水线：事先用棋盘格标定内参；每段视频用背景棋盘格估外参（并用手工尺量距离交叉验证）；SAM2 由人工提示点跟踪物体、取 mask 质心作 2D 位置；<strong>深度通过实验设计固定</strong>——物体只在与相机平面平行的平面内运动，深度事先测量。得到 3D 轨迹后，重力与摩擦场景对位置做二次拟合取加速度，粘度场景做线性拟合取终端速度（视频剪裁保证首帧已达终端速度），再代公式换算。</p><p><strong>关键的自检。</strong> 论文先把这套流水线跑在自己实拍的 ground truth 视频上（表 2）：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span></span></span> 直落 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">9.78</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">±</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.38</span></span></span></span>、抛物 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">9.85</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">±</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.36</span></span></span></span>（真值 9.81）；甘油 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1.22</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">±</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.01</span></span></span></span>（真值 1.2 Pa·s）、玉米糖浆 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">5.84</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">±</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.02</span></span></span></span>（可接受区间 5.0–7.0）、蜂蜜 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">13.82</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">±</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.75</span></span></span></span>（真值 14.1）；摩擦系数木 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.35</span></span></span></span>、橡胶 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.93</span></span></span></span>、80 目砂纸 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1.06</span></span></span></span>、3000 目砂纸 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.30</span></span></span></span>、塑料 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.22</span></span></span></span>，全部落在或贴近文献区间。这一步是全文可信度的基石。</p><p><strong>补充：语言子集。</strong> 从 181 段视频各写 1 道自然语言题（True/False 或最多 4 选项），给 VLM 看 9 帧（与 Cosmos 输入相同）后作答。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p><strong>摩擦系数。</strong> 钢块沿倾角 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span></span></span></span> 斜面下滑，沿斜面方向受重力分量 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">m</span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">sin</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span></span></span></span> 与动摩擦力 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">μ</span><span class="mord mathnormal">m</span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">cos</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span></span></span></span>，牛顿第二定律给出 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">ma</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">m</span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">sin</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">μ</span><span class="mord mathnormal">m</span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">cos</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span></span></span></span>，解得</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">μ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.2519em;vertical-align:-0.8804em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3714em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">cos</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">sin</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal">a</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.8804em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span></span></span></span> 事先量好，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">a</span></span></span></span> 由 3D 轨迹的二次拟合系数得到。注意这个式子对 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">a</span></span></span></span> 的敏感度是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord" style="margin-right:0.0556em;">∂</span><span class="mord mathnormal">μ</span><span class="mord">/</span><span class="mord" style="margin-right:0.0556em;">∂</span><span class="mord mathnormal">a</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">−</span><span class="mord">1/</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">cos</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="mclose">)</span></span></span></span>，也就是说加速度估计每偏差 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0641em;vertical-align:-0.25em;"></span><span class="mord">1</span><span class="mspace"> </span><span class="mord"><span class="mord mathrm">m/</span><span class="mord"><span class="mord mathrm">s</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathrm mtight">2</span></span></span></span></span></span></span></span></span></span></span></span>，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">μ</span></span></span></span> 就偏 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.1</span></span></span></span> 左右——这个量级很快会在 §9 变得重要。</p><p><strong>粘度。</strong> 钢球在流体中下落，达到终端速度时重力、浮力、Stokes 阻力平衡：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.1901em;vertical-align:-0.345em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8451em;"><span style="top:-2.655em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">3</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.394em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">4</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.345em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">3</span></span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">ρ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">s</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">ρ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord">6</span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="mord mathnormal" style="margin-right:0.0359em;">η</span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，整理得</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">η</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.3271em;vertical-align:-0.836em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.4911em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">9</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">2</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">ρ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">s</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord mathnormal">ρ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.836em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7167em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">ρ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">s</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">ρ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 分别是钢球与流体密度，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 由位置-时间直线拟合的斜率给出。这里的隐含前提是低雷诺数层流——甘油、玉米糖浆、蜂蜜的粘度足够高，这个前提在实拍上成立（表 2 的验证支持这点）；但<strong>生成视频不受这个约束</strong>，模型完全可能生成一段雷诺数远超 Stokes 适用范围的下落，此时公式换算出的「粘度」不再有物理含义。</p><p><strong>加速度估计。</strong> 对 3D 位置序列做二次拟合 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.1901em;vertical-align:-0.345em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8451em;"><span style="top:-2.655em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">2</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.394em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.345em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mord mathnormal">a</span><span class="mord"><span class="mord mathnormal">t</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7651em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，取二次项系数的两倍。这一步在生成视频上的脆弱性也很直接：若模型生成的轨迹并非严格二次（比如中途速度突变），拟合出的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">a</span></span></span></span> 是某种平均，其标准差会很大——实测结果里普遍出现的巨大标准差正是这个现象的表现。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>被测模型：Cosmos-1（自回归 5B、扩散 7B，扩散版分 33 帧与 121 帧两种续写长度）、Cosmos-2（2B、14B）、Cosmos-2.5（2B）；图生视频模型 Wan 2.2、HunyuanVideo、CogVideoX。论文明确说明当时 Cosmos 是唯一开源的 video-to-video WFM。</p><p><strong>问题一：模型能不能预测出正确的场景演化？</strong> 仿真子集前景 mIoU 均值：Cosmos-1 扩散 33 帧 0.4508 最高，Cosmos-1 自回归 0.4225，Cosmos-2.5 0.3488，Cosmos-2 2B 0.3201，Cosmos-2 14B 0.2684，Cosmos-1 扩散 121 帧 0.2573 最低。两个结论刺眼：<strong>同族更大的模型更差</strong>（Cosmos-2 14B 0.2684 &lt; 2B 0.3201），<strong>同一模型续写更长更差</strong>（121 帧 0.2573 &lt; 33 帧 0.4508）。附录里的时序分析进一步显示 mIoU 与预测时长成反比，且在模型开始预测的第 5 或第 9 帧处出现陡降，随后持续衰减——这是复合误差的典型曲线。实拍子集均值排序略有不同（Cosmos-1 AR 0.4112 最高，Cosmos-2 2B 0.3783），但量级一致。</p><p><strong>问题二：视觉合理是否等于物理精确？</strong> 不等于，这是全文最重要的结论。表 4（实拍）里，自由落体的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span></span></span> 估计：Cosmos-2 2B <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">8.927</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">±</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">4.791</span></span></span></span>、14B <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">8.428</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">±</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">3.478</span></span></span></span> 相对最接近；Cosmos-2.5 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">4.778</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">±</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">4.474</span></span></span></span>、Cosmos-1 AR <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">4.215</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">±</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">3.713</span></span></span></span>、Cosmos-1 DM <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">3.506</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">±</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1.912</span></span></span></span> 全部严重低估；而三个图生视频模型近乎完全失效——Wan 2.2 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">0.378</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">±</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.784</span></span></span></span>、HunyuanVideo <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">0.369</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">±</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.788</span></span></span></span>、CogVideoX <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">−</span><span class="mord">0.039</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">±</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.136</span></span></span></span>（负值意味着球在<strong>减速</strong>下落）。抛物线场景 Cosmos-2 14B <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">9.145</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">±</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">4.171</span></span></span></span> 最接近真值。论文指出，模型多数时候都能画出形状正确的抛物线或直落，但数值全错。仿真子集上则出现相反方向的偏差：Cosmos-1 AR <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">10.831</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">±</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2.925</span></span></span></span>、Cosmos-2.5 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">10.494</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">±</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">3.934</span></span></span></span> 过冲，Cosmos-2 2B 抛物线甚至给到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">13.229</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">±</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">4.312</span></span></span></span>。</p><p><strong>问题三：哪些参数更难？</strong> 粘度全线崩溃——甘油真值 1.2 而 Cosmos-1 AR 给 7.8、HunyuanVideo 给 7.203；蜂蜜真值 14.1 而多数模型给 1–3，Cosmos-2 2B 给出 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">9.845</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">±</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">6.198</span></span></span></span> 已是最接近的。论文推测原因是流体动力学训练数据稀缺。摩擦相对容易，且<strong>模型普遍给出了正确的材料排序</strong>（终端速度从慢到快依次是 80 目砂纸、橡胶、木、3000 目砂纸、塑料），说明模型学到了序关系而非数值。</p><p><strong>问题四：失败是分布差异还是理解缺失？</strong> 论文报告所有模型在仿真与实拍两版上表现相近，据此认为失败<strong>不是</strong>真实-合成域差，而是物理理解本身的缺失。</p><p><strong>其他诊断。</strong> 长尾材料（极高粘度的蜂蜜、极低摩擦的塑料）被系统性地拉向平均值，且方差<strong>没有</strong>相应增大——模型在错误上是一致的，不是不确定。交互时间越长的场景表现越好（斜坡、桌面、墙壁优于双物体下落、双物体抛物、多米诺），摩擦实验（缓慢下滑）也优于重力与粘度。训练先验主导：球滚下斜坡处理得好，球与坡底方块的交互就差；抛掷篮球的重力预测优于方块或台球。</p><p><strong>语言子集。</strong> 表 7 里 Claude Sonnet 4 平均 0.5027 最高、Gemini 2.5 Pro 0.4972、Gemini 2.5 Flash 0.4751；开源侧 Qwen2.5-VL-32B 与 GLM 4.1V 9B 并列 0.4641，且 32B 反超 72B（0.4309）；GPT 4.1 只有 0.3701，Llama-3.2-11B-Vision 0.2873。所有模型只比随机猜略好。<strong>正文写「Gemini 2.5 Pro 总体最佳（49.72%）」，而表中 Claude Sonnet 4 的 0.5027 更高</strong>，两处不一致，以表为准。分类别看，物体恒存性最难、运动物理最好；Walls 场景上 Qwen 系列接近 0.0 而两个 Gemini 都超过 0.6。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版。</strong> 现有物理 benchmark 把多个概念纠缠在同一场景、或用二值指标输出，因此既不能定位失败也不能区分视觉合理与物理精确。WorldBench 拆成两个子集：直觉物理理解（4 概念 15 场景 469 段，用 SAM2 前景 mIoU 与背景 RMSE 评）与物理参数估计（重力、粘度、摩擦共 279 段，用棋盘格标定 + 恒定深度设计直接反解出有单位的数）。反解流水线先在实拍 ground truth 上验证通过（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span></span></span> 量到 9.78/9.85，粘度与摩擦均落在文献区间），才用于评测模型。结果是所有被测模型都能画出形状正确的轨迹却给不出正确的数值：Cosmos 系列的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span></span></span> 在 3.5–10.8 之间大幅波动且方差巨大，图生视频模型几乎完全失效（CogVideoX 甚至给出负重力）。附加发现包括更大模型更差、续写更长更差、长尾材料被拉向均值、模型更依赖训练先验而非物理定律，而仿真与实拍表现相近说明问题不在域差。</p><p><strong>3 句话版。</strong> 世界模型宣称能当合成数据生成器，但没人验证过它生成的物理参数是否正确。WorldBench 用受控实拍装置把深度固定、把概念隔离，从生成视频里直接反解重力加速度、粘度与摩擦系数。结论是轨迹形状对、数值全错，且模型规模与预测长度的增加都会让情况变差。</p><p><strong>1 句话版。</strong> 世界模型画得出抛物线，量不出 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0641em;vertical-align:-0.25em;"></span><span class="mord">9.8</span><span class="mspace"> </span><span class="mord"><span class="mord mathrm">m/</span><span class="mord"><span class="mord mathrm">s</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathrm mtight">2</span></span></span></span></span></span></span></span></span></span></span></span>。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最致命的假设是：<strong>从生成视频里用二次/线性拟合反解出的参数，在生成视频上仍具有与真实视频相同的物理含义</strong>。整个参数子集的结论都建立在这个迁移之上。</p><p>它在实践中很可能不成立，理由是具体的。真实视频满足公式的前提：轨迹严格是抛体运动、深度恒定、Stokes 层流成立、物体刚性不变形、尺度由标定确定。生成视频<strong>不受任何这些约束</strong>——模型完全可能让球在下落中改变视觉尺寸（隐含深度变化）、让钢球在糖浆中忽快忽慢（非终端速度）、让斜面角度在续写中漂移、甚至让物体形态畸变（论文的图 10 就展示了自回归模型严重扭曲物体形状、扩散模型把花瓶幻觉成坦克并加上一只人手）。一旦这些前提破裂，拟合出的「加速度」不再是加速度，代进 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">μ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">sin</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">a</span><span class="mclose">)</span><span class="mord">/</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">cos</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="mclose">)</span></span></span></span> 得到的也不再是摩擦系数。</p><p>论文提供的证据只覆盖了一半：表 2 验证了流水线在<strong>真实视频</strong>上准确，这是必要条件但不是充分条件。缺失的是在<strong>已知错误的生成视频</strong>上的行为刻画——比如人为合成一段「球以 9.8 加速下落但同时被放大 20%」的视频，看流水线会给出什么。间接反证其实已经出现在结果里：几乎所有模型的重力估计标准差都在 2–5 之间（Cosmos-2 2B 是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">8.927</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">±</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">4.791</span></span></span></span>），也就是<strong>标准差与均值同量级</strong>。论文把这解释成「模型 rollout 间方差极高」，但同样自洽的解释是「轨迹不符合二次形式，拟合本身在报噪声」。这两种解释目前无法区分，而它们对结论的含义完全不同。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不需要跑任何 WFM，一周内可完成对上述假设的检验：</p><ul><li><strong>数据</strong>：取 WorldBench 实拍的 17 段自由落体视频（已验证流水线在其上给出 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">9.78</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">±</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.38</span></span></span></span>）。</li><li><strong>实现</strong>：只重实现反解流水线（棋盘格标定 + SAM2 质心 + 二次拟合，全部是现成库）。然后构造四组<strong>受控退化</strong>版本：(A) 对帧序列做逐帧线性缩放，模拟深度漂移；(B) 在轨迹中段插入一次速度阶跃；(C) 对物体做逐帧非刚性形变（质心因此抖动）；(D) 随机丢弃 20% 帧再插值，模拟时序不一致。每组退化幅度取三档。</li><li><strong>测量</strong>：每组退化后重跑流水线，记录 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.2222em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span></span></span></span> 的均值与标准差。</li><li><strong>判据</strong>：若某一档退化就能让 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.2222em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span></span></span></span> 从 9.78 落到 4–5 区间（即论文报告的 Cosmos-1 水平），同时标准差涨到 2–4（即论文报告的量级），那么「模型重力估计偏低」这一核心结论就有了一个完全不涉及物理理解的替代解释——它可能只是在测量生成视频的几何不稳定性。若四组退化都无法复现该模式（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.2222em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span></span></span></span> 保持在 8 以上），则论文的假设经受住了检验，参数级评测确实在测物理。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p><strong>替代解释：参数估计的排名可能主要由「模型是否保持物体外观稳定」决定，而非物理理解。</strong> 支持这个替代解释的证据在论文自己的数据里：mIoU 排名与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span></span></span> 估计排名并不一致（Cosmos-1 33F 的 mIoU 最高 0.4508，但它的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span></span></span> 是 3.506，最差之一；Cosmos-2 14B 的 mIoU 最低之一 0.2684，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span></span></span> 却是 8.428，最好之一）。这本身说明两个子集在测不同的东西——但也说明参数估计对「模型画得像不像」不敏感，反而可能对「质心轨迹是否平滑」高度敏感。而 §5 的流水线正是用 mask 质心作为唯一的位置信号：任何让 mask 形状随时间变化的现象（视角旋转、遮挡、形变、纹理漂移）都会污染质心，进而污染二次拟合。</p><p>据此设计的攻击是：对每个模型，在同一批生成视频上同时计算 (i) 反解出的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.2222em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span></span></span></span>、(ii) mask 面积的时间变异系数、(iii) mask 长宽比的时间变异系数。若 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.2222em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span></span></span></span> 与 (ii)(iii) 的相关性高于它与任何物理量的相关性，则参数子集在很大程度上是一个「外观稳定性 benchmark」的伪装，论文「首次定量测量世界模型物理精确性」的 claim 需要大幅弱化。</p><p>第二条攻击线针对 I2V 模型的对比公平性。论文承认图生视频模型「输入缺乏时间信息」，但仍把它们与拿到多帧输入的 Cosmos 放在同一张表里比 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span></span></span>。CogVideoX 给出 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">−</span><span class="mord">0.039</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">±</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.136</span></span></span></span> 这样的数字，其实说明它生成的几乎是<strong>静止</strong>的球——这是任务不匹配（单帧无法确定初速度方向与大小），不是物理理解缺失。可预测的失败条件因此很明确：任何单帧条件的模型在重力子集上都会给出接近 0 的估计，这一列数据的信息量接近于零。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>把评测从「量参数」推进到「量参数的可控性」：不只问模型生成的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span></span></span> 是多少，而是问能否通过条件把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span></span></span> 系统性地推到指定值。</strong></p><p>(a) <strong>驱动局限</strong>：WorldBench 揭示的现象——轨迹形状对、数值错、长尾材料被拉向均值、方差与均值同量级——共同指向一个诊断：模型在参数维度上<strong>几乎没有可控自由度</strong>，它在采样一个宽而集中的先验分布，而不是在执行一个条件。但论文的评测只能观测到这个分布的一阶矩与二阶矩，无法区分「模型不知道 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span></span></span>」与「模型知道但条件通道没接上」。这个区分对下游极其重要：前者需要重新训练，后者只需改条件化。</p><p>(b) <strong>可借鉴的相邻领域</strong>：因果推断里的<strong>干预</strong>（do-operator）与可辨识性分析，以及控制论里的<strong>能控性</strong>（controllability）。这两套工具都在问同一件事——改变输入能否让系统状态到达指定目标，而不是被动观测输出分布。</p><p>(c) <strong>新 framing</strong>：把世界模型当作一个待检验的<strong>受控系统</strong>，评测其物理参数的能控性。具体做法是：对同一初始帧，用不同的文本/数值条件（「月球重力」「地球重力」「木星重力」，或直接给数值）驱动生成，反解出 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.2222em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span></span></span></span> 序列，度量两件事——<strong>单调性</strong>（条件递增时 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.2222em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span></span></span></span> 是否递增）与<strong>增益</strong>（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">Δ</span><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.2222em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span><span class="mord">/Δ</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">cmd</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 距离 1 有多远）。这与现有工作的差别是根本的：现有评测全部是被动观测，而这里做的是主动干预，且给出的是一个控制论意义上的传递特性，而非一个准确率。</p><p>(d) <strong>第一个实验</strong>：直接复用 WorldBench 的重力装置，最省事。取 17 段直落视频的首帧，对每段用 5 档重力条件（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1.6</span></span></span></span> 月球、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">3.7</span></span></span></span> 火星、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">9.8</span></span></span></span> 地球、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">24.8</span></span></span></span> 木星，外加不给条件）驱动 Cosmos-2 2B（该模型在 §7 里 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span></span></span> 估计相对最好），每档 5 个种子。度量 Spearman 单调性与线性回归斜率。判据：若单调性显著（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7335em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ρ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&gt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.7</span></span></span></span>）但斜率远小于 1（比如 0.2），说明条件通道是通的、只是增益被压缩，改进方向是条件化强度而非重新训练；若单调性不显著，则模型确实在无视条件采样先验，与论文「依赖训练先验而非物理定律」的观察形成互证，且给出了一个比 mIoU 更直接的诊断量。</p>',65)])])}const d=a(l,[["render",e]]);export{o as __pageData,d as default};
